17	
18	    @ExceptionHandler(ApiException.class)
19	    public org.springframework.http.ResponseEntity<ApiError> handleApi(ApiException ex) {
20	        return org.springframework.http.ResponseEntity.status(ex.getStatus())
21	                .body(new ApiError(ex.getCode(), ex.getMessage()));
22	    }
23	
24	    @ExceptionHandler({MissingRequestHeaderException.class, MethodArgumentNotValidException.class,
25	            ConstraintViolationException.class, HttpMessageNotReadableException.class})
26	    public org.springframework.http.ResponseEntity<ApiError> handleBadRequest(Exception ex) {
27	        String message = "请求参数不合法";
28	        if (ex instanceof MissingRequestHeaderException header) {
29	            message = "缺少请求头 " + header.getHeaderName();
30	        } else if (ex instanceof MethodArgumentNotValidException validation
31	                && validation.getBindingResult().getFieldError() != null) {
32	            message = validation.getBindingResult().getFieldError().getDefaultMessage();
33	        } else if (ex instanceof ConstraintViolationException violation
34	                && !violation.getConstraintViolations().isEmpty()) {
35	            message = violation.getConstraintViolations().iterator().next().getMessage();
36	        }
37	        return org.springframework.http.ResponseEntity.status(HttpStatus.BAD_REQUEST)
38	                .body(new ApiError("BAD_REQUEST", message));
39	    }
40	}
